export type StoryFlagOp = { key: string; value: unknown };

/** Накапливается в батче; мутации NPC выполняет хук состояния после чистого прохода. */
export type ChoiceBatchSideEffects = {
  npcRelDeltas: Array<{
    npcId: string;
    trust?: number;
    affection?: number;
    respect?: number;
    fear?: number;
  }>;
