/**
 * После npc_mark_dead: зачесть цели defeat_enemy, обновить статистику, строку журнала о бое.
 * Идемпотентно по квесту: одна и та же цель не даст двойного зачёта при повторном вызове.
 */
export function applyDefeatEnemyProgressForMarkedDead(
  player: Player,
  npcId: string,
  lang: Language,
  log: WorldLogEntry[],
): Player {
  const id = npcId.trim();
  if (!id) return player;

  let anyObjectiveDone = false;

  const activeQuests = player.storyProgress.activeQuests.map((q) => {
    let qTouch = false;
    const objectives = q.objectives.map((o) => {
      if (o.type !== 'defeat_enemy' || o.completed || o.target !== id) return o;
      qTouch = true;
      anyObjectiveDone = true;
      return { ...o, completed: true, current: o.required };
    });
    return qTouch ? { ...q, objectives } : q;
  });

  if (!anyObjectiveDone) return player;

  const line = t('game.log.battle_completed_world', lang).replace('{{id}}', id);
  pushWorldLog(log, line, 'dramatic', 'combat');

  return {
    ...player,
    stats: {
      ...player.stats,
      enemiesDefeated: player.stats.enemiesDefeated + 1,
      battlesWon: player.stats.battlesWon + 1,
    },
    storyProgress: {
      ...player.storyProgress,
      activeQuests,
      worldEventLog: log,
    },
  };
}

/**
 * Версия сериализованного снимка (`chronos_save` / IndexedDB).
 * Увеличивать при несовместимых изменениях структуры + добавить шаг в `migratePersistedSaveRevived`.
 */
export const CHRONOS_SAVE_SCHEMA_VERSION = 2;

export type PersistedChronosSave = {
  saveSchemaVersion?: number;
  timestamp: number;
  /** Прочие поля задаёт `useGameState` — тип минимальный для миграций. */
  [key: string]: unknown;
};

export type MigratePersistedSaveResult =
  | { ok: true }
  | { ok: false; reason: 'unsupported_forward_schema'; version: number };

/** После `reviveMaps`: поднять версию и подлатать поля между версиями. */
export function migratePersistedSaveRevived(data: PersistedChronosSave): MigratePersistedSaveResult {
  const from = typeof data.saveSchemaVersion === 'number' ? data.saveSchemaVersion : 1;
  if (from > CHRONOS_SAVE_SCHEMA_VERSION) {
    return { ok: false, reason: 'unsupported_forward_schema', version: from };
  }
  if (from < 2) {
    // v1 → v2: структура совместима с текущим кодом; точечные патчи при необходимости.
  }
  data.saveSchemaVersion = CHRONOS_SAVE_SCHEMA_VERSION;
  return { ok: true };
}

/**
 * Детерминированный RNG для доменных симуляций (replay/qa).
 * Не криптостойкий; предназначен для воспроизводимых игровых тиков.
 */
export type DeterministicRng = () => number;

export function seedFromString(input: string): number {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h >>> 0;
}

export function createDeterministicRng(seed: number): DeterministicRng {
  let s = (seed >>> 0) || 1;
  return () => {
    s = Math.imul(1664525, s) + 1013904223;
    s >>>= 0;
    return s / 4294967296;
  };
}

