      {
        id: '1',
        message: 'x',
        ttlHours: 100,
        originLocationId: 'a',
        factionTags: [],
        reachedLocationIds: ['a'],
      },
    ];
    const seq = [0.01, 0.9, 0.02, 0.95, 0.03];
    const mkRng = () => {
      let i = 0;
      return () => seq[(i++) % seq.length]!;
    };
    const left = decayAndSpreadRumors(rumors, 24, adj, mkRng());
