export function factionTagsForGossipNpc(npc: {
  professionKey?: string;
  title?: string;
}): string[] {
  const pk = npc.professionKey ?? '';
  const title = npc.title?.toLowerCase() ?? '';
  if (pk === 'thief' || pk === 'rogue' || title.includes('rogue')) return ['thieves_guild'];
