import { describe, expect, it } from 'vitest';

import { STORY_LOCATIONS } from '@/domain/world/storyLocations';

function graphIsConnected(ids: string[], neighbors: Map<string, string[]>): boolean {
  if (!ids.length) return true;
  const seen = new Set<string>();
  const q: string[] = [ids[0]!];
  while (q.length > 0) {
    const id = q.shift()!;
    if (seen.has(id)) continue;
    seen.add(id);
    for (const n of neighbors.get(id) ?? []) {
      if (!seen.has(n)) q.push(n);
    }
  }
  return seen.size === ids.length;
}

describe('storyLocations graph', () => {
  it('uses unique location ids', () => {
    const ids = STORY_LOCATIONS.map((l) => l.id);
    expect(new Set(ids).size).toBe(ids.length);
  });

  it('has only known neighbors and symmetric edges', () => {
    const ids = new Set(STORY_LOCATIONS.map((l) => l.id));
    const byId = new Map(STORY_LOCATIONS.map((l) => [l.id, l]));
    for (const loc of STORY_LOCATIONS) {
      for (const n of loc.connectedLocations) {
        expect(ids.has(n)).toBe(true);
        expect(byId.get(n)?.connectedLocations.includes(loc.id)).toBe(true);
      }
    }
  });

  it('stays connected for the playable region graph', () => {
    const ids = STORY_LOCATIONS.map((l) => l.id);
    const neighbors = new Map(STORY_LOCATIONS.map((l) => [l.id, l.connectedLocations]));
    expect(graphIsConnected(ids, neighbors)).toBe(true);
  });
});

// Загрузка ассетов Kimi / Art Bible: атлас мира 32×32, fallback если файлов ещё нет.
import type { BiomeKind } from '@/engine/worldTiles';
import { CHRONOS_ASSETS_BASE } from '@/domain/assets/chronosGraphicsRegistry';

export const CHRONOS_TILE_ART_PX = 32;
export { CHRONOS_ASSETS_BASE };

export interface WorldAtlasFrames {
  image: HTMLImageElement;
  /** biome_var01 → { x,y,w,h } в пикселях атласа */
  frames: Record<string, { x: number; y: number; w: number; h: number }>;
}

let cachedAtlas: WorldAtlasFrames | null = null;

export function resolveAtlasFrame(
  atlas: WorldAtlasFrames,
  baseName: string
): { x: number; y: number; w: number; h: number } | null {
  return atlas.frames[`${baseName}.png`] ?? atlas.frames[baseName] ?? null;
}

/** Путь к JSON TexturePacker / простому { frames: { name: {frame:{x,y,w,h}} } } */
export async function tryLoadWorldAtlas(): Promise<WorldAtlasFrames | null> {
  if (cachedAtlas) return cachedAtlas;
  const jsonUrl = `${CHRONOS_ASSETS_BASE}atlas/atlas_world_v01.json`;
  const imgUrl = `${CHRONOS_ASSETS_BASE}atlas/atlas_world_v01.png`;
  try {
    const [jsonRes, img] = await Promise.all([
      fetch(jsonUrl, { cache: 'no-store' }),
      new Promise<HTMLImageElement>((resolve, reject) => {
        const im = new Image();
        im.crossOrigin = 'anonymous';
        im.onload = () => resolve(im);
        im.onerror = () => reject(new Error('atlas img'));
        im.src = imgUrl;
      })
    ]);
    if (!jsonRes.ok) return null;
    const data = (await jsonRes.json()) as {
      frames?: Record<string, { frame: { x: number; y: number; w: number; h: number } }>;
    };
    const raw = data.frames ?? {};
    const frames: WorldAtlasFrames['frames'] = {};
    for (const [name, v] of Object.entries(raw)) {
      const f = v?.frame;
      if (f) frames[name] = { x: f.x, y: f.y, w: f.w, h: f.h };
    }
    if (Object.keys(frames).length === 0) return null;
    cachedAtlas = { image: img, frames };
    return cachedAtlas;
  } catch {
    return null;
  }
}

/** Сброс кэша (например после смены версии ассетов). */
export function clearWorldAtlasCache(): void {
  cachedAtlas = null;
}

/** Имя кадра для биома: biome_plains_var01 … var06 по хэшу тайла */
export function atlasFrameNameForBiome(biome: BiomeKind, tileX: number, tileY: number, seed: number): string {
  let h = seed ^ Math.imul(tileX, 0x9e3779b1) ^ Math.imul(tileY, 0x517cc1b7);
  h >>>= 0;
  const v = (h % 6) + 1;
  const pad = v < 10 ? `0${v}` : String(v);
  return `biome_${biome}_var${pad}`;
}

import { useEffect, useState } from 'react';

/**
 * Пауза тяжёлого рендера при свёрнутом окне / фоне (MVP 070).
 * Браузер: Page Visibility; Electron: IPC minimize/restore из preload.
 */
export function useChronosPowerSavePaused(): boolean {
  const [paused, setPaused] = useState(() =>
    typeof document !== 'undefined' ? document.visibilityState === 'hidden' : false,
  );

  useEffect(() => {
    const api = typeof window !== 'undefined' ? window.chronosDesktop : undefined;
    let electronOccluded = false;

    const apply = () => {
      setPaused(document.visibilityState === 'hidden' || electronOccluded);
    };

    document.addEventListener('visibilitychange', apply);

    let unsub: (() => void) | undefined;
    if (api?.onOcclusionChanged) {
      unsub = api.onOcclusionChanged(({ occluded }) => {
        electronOccluded = occluded;
        apply();
      });
    }

    apply();

    return () => {
      document.removeEventListener('visibilitychange', apply);
      unsub?.();
    };
  }, []);

  return paused;
}

import { createContext, useContext, useEffect, useMemo, useState } from 'react';
import type { Language } from './index';
import { getLanguage } from './index';
import { CHRONOS_SETTINGS_STORAGE_KEY } from '@/lib/chronosGameSettings';

type LanguageContextValue = {
  language: Language;
};

const LanguageContext = createContext<LanguageContextValue>({ language: 'ru' });

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [language, setLanguage] = useState<Language>(() => getLanguage());

  useEffect(() => {
    if (typeof document !== 'undefined') {
      document.documentElement.lang = language === 'en' ? 'en' : 'ru';
    }
  }, [language]);

  useEffect(() => {
    const onStorage = (e: StorageEvent) => {
      if (e.key === CHRONOS_SETTINGS_STORAGE_KEY) setLanguage(getLanguage());
    };
    const onCustom = () => setLanguage(getLanguage());
    window.addEventListener('storage', onStorage);
    window.addEventListener('chronos:settings_updated', onCustom);
    return () => {
      window.removeEventListener('storage', onStorage);
      window.removeEventListener('chronos:settings_updated', onCustom);
    };
  }, []);

  const value = useMemo(() => ({ language }), [language]);
  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage(): Language {
  return useContext(LanguageContext).language;
}

import type { WorldGraphicsTier } from '@/types/chronosGraphics';
import { CHRONOS_SETTINGS_STORAGE_KEY } from '@/lib/chronosGameSettings';

export function readWorldGraphicsTier(): WorldGraphicsTier {
  try {
    const raw = localStorage.getItem(CHRONOS_SETTINGS_STORAGE_KEY);
    if (!raw) return 'balanced';
    const j = JSON.parse(raw) as { worldGraphicsTier?: string };
    const t = j.worldGraphicsTier;
    if (t === 'low' || t === 'balanced' || t === 'high') return t;
    return 'balanced';
  } catch {
    return 'balanced';
  }
}

import { useThree } from '@react-three/fiber';
import { useEffect, useMemo } from 'react';
import * as THREE from 'three';
import { createChronosCubeEnv } from '@/rendering/chronosEnvMap';

/** PMREM окружения для металла / воды / «SSR»-фолбэка. */
export function ChronosEnvironment() {
  const { gl, scene } = useThree();
  const pmrem = useMemo(() => new THREE.PMREMGenerator(gl), [gl]);
  const envRT = useMemo(() => {
    const cube = createChronosCubeEnv();
    const rt = pmrem.fromCubemap(cube);
    cube.dispose();
    return rt;
  }, [pmrem]);

  useEffect(() => {
    const prev = scene.environment;
    scene.environment = envRT.texture;
    return () => {
      scene.environment = prev;
      envRT.dispose();
      pmrem.dispose();
    };
  }, [scene, envRT, pmrem]);

  return null;
}

/**
 * Заготовка behavior tree: узлы возвращают статус тика.
 * Расширять доменными действиями и условиями; не тащить тяжёлый ИИ в корень дерева без профилирования.
 */

export type BTStatus = 'success' | 'failure' | 'running';

export interface BTNode<Context> {
  tick(ctx: Context): BTStatus;
}

export class Sequence<Context> implements BTNode<Context> {
  private readonly children: readonly BTNode<Context>[];

  constructor(children: readonly BTNode<Context>[]) {
    this.children = children;
  }

  tick(ctx: Context): BTStatus {
    for (const child of this.children) {
      const s = child.tick(ctx);
      if (s === 'failure' || s === 'running') return s;
    }
    return 'success';
  }
}

export class Selector<Context> implements BTNode<Context> {
  private readonly children: readonly BTNode<Context>[];

  constructor(children: readonly BTNode<Context>[]) {
    this.children = children;
  }

  tick(ctx: Context): BTStatus {
    for (const child of this.children) {
      const s = child.tick(ctx);
      if (s === 'success' || s === 'running') return s;
    }
    return 'failure';
  }
}

