import * as THREE from 'three';

/** Процедурный cube env (cyan / violet / aurora) — отражения для металла и воды без CubeCamera. */
export function createChronosCubeEnv(): THREE.CubeTexture {
  const size = 96;
  const gradients: [string, string][] = [
    ['#010409', '#111827'],
    ['#030712', '#312e81'],
    ['#020617', '#134e4a'],
    ['#0f0720', '#581c87'],
    ['#082f49', '#67e8f9'],
    ['#020617', '#155e75']
  ];
  const images: HTMLCanvasElement[] = [];
  for (let f = 0; f < 6; f++) {
    const c = document.createElement('canvas');
    c.width = size;
    c.height = size;
    const ctx = c.getContext('2d')!;
    const [a, b] = gradients[f % gradients.length];
    const g = ctx.createLinearGradient(0, 0, size, size);
    g.addColorStop(0, a);
    g.addColorStop(0.55, b);
    g.addColorStop(1, '#66fcf1');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, size, size);
    ctx.globalAlpha = 0.18;
    for (let i = 0; i < 55; i++) {
      const tw = 1 + (i % 3);
      ctx.fillStyle = `hsl(${210 + (f * 9 + i * 5) % 100}, 72%, ${38 + (i % 6) * 7}%)`;
      ctx.fillRect((i * 19) % size, (i * 29 + f * 7) % size, tw, tw);
    }
    images.push(c);
  }
  const tex = new THREE.CubeTexture(images);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.needsUpdate = true;
  return tex;
}

/**
 * Минимальный «ECS-лайт»: сущности и компоненты без полноценного ECS-движка.
 * Для тяжёлой симуляции рассмотреть вынос систем в отдельный модуль и batch-обновление.
 */

export type EntityId = number;

export type ComponentKey = string;

export type ComponentBag = Readonly<Record<ComponentKey, unknown>>;

export class EcsLite {
  private nextId = 1 as EntityId;
  private readonly entities = new Map<EntityId, Record<ComponentKey, unknown>>();

  spawn(components: Record<ComponentKey, unknown>): EntityId {
    const id = this.nextId;
    this.nextId = (id + 1) as EntityId;
    this.entities.set(id, { ...components });
    return id;
  }

  despawn(id: EntityId): void {
    this.entities.delete(id);
  }

  getComponent<K extends ComponentKey>(id: EntityId, key: K): unknown {
    return this.entities.get(id)?.[key];
  }

  setComponent<K extends ComponentKey>(id: EntityId, key: K, value: unknown): void {
    const e = this.entities.get(id);
    if (!e) return;
    e[key] = value;
  }
}

/**
 * Синхронный CSS2DRenderer поверх WebGL — подписи и «пузыри» в мировых координатах.
 */
import { useThree, useFrame } from '@react-three/fiber';
import { useLayoutEffect, useMemo } from 'react';
import { CSS2DRenderer } from 'three/examples/jsm/renderers/CSS2DRenderer.js';

export function Css2DWorldOverlay() {
  const { gl, scene, camera, size } = useThree();

  const labelRenderer = useMemo(() => new CSS2DRenderer(), []);

  useLayoutEffect(() => {
    const el = labelRenderer.domElement;
    el.style.position = 'absolute';
    el.style.top = '0';
    el.style.left = '0';
    el.style.pointerEvents = 'none';
    el.style.zIndex = '10';
    const parent = gl.domElement.parentElement;
    if (!parent) return;
    el.classList.add('chronos-css2d-host');
    parent.appendChild(el);
    return () => {
      if (el.parentElement) el.parentElement.removeChild(el);
      labelRenderer.domElement.replaceChildren();
    };
  }, [gl, labelRenderer]);

  useLayoutEffect(() => {
    labelRenderer.setSize(size.width, size.height);
  }, [labelRenderer, size]);

  useFrame(() => {
    labelRenderer.render(scene, camera);
  }, 1000);

  return null;
}

