  const [scenes, setScenes] = useState<Map<string, THREE.Group>>(new Map());
  const groupRef = useRef<THREE.Group>(null);
  const visiblePathRef = useRef<string | null>(null);

  const enabled = tierRank(graphicsTier) >= tierRank(minTier);
  const activePaths = useMemo(() => {
    const list = lodPaths?.length ? lodPaths : [path];
    return Array.from(new Set(list));
  }, [lodPaths, path]);

  useEffect(() => {
    if (!enabled) return;
    const next = new Map<string, THREE.Group>();
    let alive = true;

    const loader = new GLTFLoader();
    const base = import.meta.env.BASE_URL || '/';
    const loads = activePaths.map(
      (assetPath) =>
        new Promise<void>((resolve) => {
          const url = `${base}${assetPath}`.replace(/([^:]\/)\/+/g, '$1');
          loader.load(
            url,
            (gltf) => {
              const root = gltf.scene;
              root.traverse((o) => {
                const m = o as THREE.Mesh;
                if (m.isMesh) {
                  m.castShadow = true;
                  m.receiveShadow = true;
                }
              });
              next.set(assetPath, root);
              resolve();
            },
            undefined,
            () => resolve()
          );
        })
    );

    Promise.all(loads).then(() => {
      if (!alive) {
        for (const scene of next.values()) {
          disposeScene(scene);
        }
        return;
      }
      setScenes(next);
    });

    return () => {
      alive = false;
      setScenes((prev) => {
        for (const scene of prev.values()) {
          disposeScene(scene);
        }
        return new Map

/**
 * Пул объектов: снижает GC-пиков в горячих циклах (частицы, временные векторы-обёртки и т.д.).
 * reset вызывается при возврате в пул; factory — при исчерпании свободных слотов (до maxSize).
 */

export class ObjectPool<T> {
  private readonly free: T[] = [];
  private readonly factory: () => T;
  private readonly reset: (item: T) => void;
  private readonly maxSize: number;

  constructor(factory: () => T, reset: (item: T) => void, maxSize: number) {
    this.factory = factory;
    this.reset = reset;
    this.maxSize = maxSize;
  }

  acquire(): T {
    const item = this.free.pop() ?? this.factory();
    return item;
  }

  release(item: T): void {
    if (this.free.length >= this.maxSize) return;
    this.reset(item);
    this.free.push(item);
  }
}

