/**
 * Отложенная доля последствий распространения слухов по фракциям (MVP 083).
 * Часть дельты применяется сразу, остальное — после игровых часов (очередь на advanceTime).
 */
import type { RumorConsequencePending } from '@/types/game';

/** Доля репутационного эффекта слуха, переносимая на отложенный «отклик». */
export const CHRONOS_RUMOR_REP_RIPPLE_FRACTION = 0.38;

/** Базовая задержка перед отложенной долей (часы), к ней добавляется детерминированный джиттер по ключу фракции. */
export const CHRONOS_RUMOR_RIPPLE_DELAY_BASE_HOURS = 8;

/** Ниже этого модуля дельты не делим — уходит целиком в немедленное применение. */
export const CHRONOS_RUMOR_RIPPLE_SPLIT_MIN_ABS = 1.15;

function jitterHoursForKey(factionKey: string): number {
  let s = 0;
  for (let i = 0; i < factionKey.length; i++) s = (s + factionKey.charCodeAt(i) * (i + 3)) % 7;
  return s;
}

export function splitRumorReputationRipple(
  rawDelta: Record<string, number>,
): { immediate: Record<string, number>; pending: RumorConsequencePending[] } {
  const immediate: Record<string, number> = {};
  const pending: RumorConsequencePending[] = [];

  for (const [k, v] of Object.entries(rawDelta)) {
    if (!Number.isFinite(v) || v === 0) continue;

    if (Math.abs(v) < CHRONOS_RUMOR_RIPPLE_SPLIT_MIN_ABS) {
      immediate[k] = (immediate[k] ?? 0) + v;
      continue;
    }

    const later = v * CHRONOS_RUMOR_REP_RIPPLE_FRACTION;
    const now = v - later;

    if (Math.abs(now) >= 1e-8) {
      immediate[k] = (immediate[k] ?? 0) + now;
    }
    if (Math.abs(later) >= 1e-8) {
      pending.push({
        id: `rumor_ripple_${k}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
        remainingHours: CHRONOS_RUMOR_RIPPLE_DELAY_BASE_HOURS + jitterHoursForKey(k),
        factionRepDelta: { [k]: later },
      });
    }
  }

  return { immediate, pending };
}

export function tickRumorConsequenceQueue(
  queue: RumorConsequencePending[],
  hoursAdvanced: number,
): { queue: RumorConsequencePending[]; releasedReputationDelta: Record<string, number> } {
  const h = Math.max(0, hoursAdvanced);
  const releasedReputationDelta: Record<string, number> = {};
  const next: RumorConsequencePending[] = [];

  for (const item of queue) {
    const rem = item.remainingHours - h;
    if (rem <= 0) {
      for (const [fk, val] of Object.entries(item.factionRepDelta)) {
        if (!Number.isFinite(val) || val === 0) continue;
        releasedReputationDelta[fk] = (releasedReputationDelta[fk] ?? 0) + val;
      }
    } else {
      next.push({ ...item, remainingHours: rem });
    }
  }

  return { queue: next, releasedReputationDelta };
}

/**
 * Чистая функция распространения слухов — может выполняться в Web Worker без доступа к NPCSystem.
 */
import type { ActiveRumor } from '@/types/game';
import {
  CHRONOS_GOSSIP_NEW_LOCATIONS_PER_SPREAD_MAX,
  CHRONOS_GOSSIP_REACHED_LOCATIONS_CAP,
} from '@/domain/social/gossipSpreadConstants';

export type RumorSpreadDTO = {
  id: string;
  ttlHours: number;
  originLocationId: string;
  reachedLocationIds: string[];
  message: string;
  severity?: 'info' | 'rumor' | 'dramatic';
  factionTags: string[];
};

export function activeRumorToDto(a: ActiveRumor): RumorSpreadDTO {
  return {
    id: a.id,
    message: a.message,
    severity: a.severity,
    ttlHours: a.ttlHours,
    originLocationId: a.originLocationId,
    factionTags: [...a.factionTags],
    reachedLocationIds: [...a.reachedLocationIds],
  };
}

export function dtoToActiveRumor(r: RumorSpreadDTO): ActiveRumor {
  return {
    id: r.id,
    message: r.message,
    severity: r.severity,
    ttlHours: r.ttlHours,
    originLocationId: r.originLocationId,
    factionTags: [...r.factionTags],
    reachedLocationIds: [...r.reachedLocationIds],
  };
}

function trimReachedLocations(r: RumorSpreadDTO, reach: Set<string>): string[] {
  const cap = CHRONOS_GOSSIP_REACHED_LOCATIONS_CAP;
  if (reach.size <= cap) return [...reach];
  const out: string[] = [];
  const seen = new Set<string>();
  const push = (id: string) => {
    if (out.length >= cap || seen.has(id)) return;
    seen.add(id);
    out.push(id);
  };
  push(r.originLocationId);
  for (const id of r.reachedLocationIds) push(id);
  for (const id of reach) push(id);
  return out;
}

/** Сжигает TTL и распространяет охват по рёбрам графа локаций. */
export function decayAndSpreadRumors(
  rumors: RumorSpreadDTO[],
  hours: number,
  adjacency: Record<string, string[]>,
  randomFn: () => number = Math.random,
): RumorSpreadDTO[] {
  const h = Math.min(168, Math.max(0, hours));
  const intensity = Math.min(1, h / 12);

  const alive = burnRumorTtl(rumors, h);

  for (const r of alive) {
    const reach = new Set(r.reachedLocationIds);
    const frontier = [...r.reachedLocationIds];
    let addedThisSpread = 0;
    spread: for (const loc of frontier) {
      const neighbors = adjacency[loc];
      if (!neighbors) continue;
      for (const next of neighbors) {
        if (reach.has(next)) continue;
        if (randomFn() < 0.12 * intensity) {
          reach.add(next);
          addedThisSpread++;
          if (addedThisSpread >= CHRONOS_GOSSIP_NEW_LOCATIONS_PER_SPREAD_MAX) break spread;
        }
      }
    }
    r.reachedLocationIds = trimReachedLocations(r, reach);
  }

  return alive;
}

/** Только сжигает TTL и отбрасывает умершие, без расширения охвата. */
export function burnRumorTtl(rumors: RumorSpreadDTO[], hours: number): RumorSpreadDTO[] {
  const h = Math.min(168, Math.max(0, hours));
  return rumors
    .map((r) => ({ ...r, ttlHours: r.ttlHours - h }))
    .filter((r) => r.ttlHours > 0);
}

